parameters.jsCode:
let raw = $input.first().json.output || "";

raw = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    entry_type: "note",
    tags: [],
    summary: "parse fallback",
    error: e.message
  };
}

const sourceText = ($('SYS_BuildInputContext').first().json.text || "").trim();
const lower = sourceText.toLowerCase();
const activityMap = [
  { pattern: /^(английский|english)\s+(\d{1,3})\b/i, code: "english" },
  { pattern: /^(лед|лёд|ice)\s+(\d{1,3})\b/i, code: "ice" },
  { pattern: /^(дриблинг|dribbling|dribble)\s+(\d{1,3})\b/i, code: "dribbling" }
];

let activity = null;
for (const item of activityMap) {
  const match = lower.match(item.pattern);
  if (match) {
    activity = {
      activity_type_code: item.code,
      duration_minutes: Number(match[2])
    };
    break;
  }
}

const allowedTrackerTypes = new Set([
  "note",
  "idea",
  "insight",
  "decision",
  "observation",
  "hypothesis",
  "task",
  "feeling"
]);

if (!allowedTrackerTypes.has(parsed.entry_type)) {
  parsed.entry_type = "note";
}

const trajectoryTypeMap = {
  note: "general_note",
  idea: "general_note",
  decision: "general_note",
  hypothesis: "general_note",
  task: "general_note",
  observation: "observation",
  insight: "insight",
  feeling: "feeling"
};

return [{
  json: {
    ...parsed,
    is_activity_event: Boolean(activity),
    activity_type_code: activity?.activity_type_code || null,
    duration_minutes: activity?.duration_minutes || null,
    trajectory_entry_type: trajectoryTypeMap[parsed.entry_type] || "general_note"
  }
}];

const entries = $input.all();

if (entries.length === 0) {
  return [{
    json: {
      reply: "📚 У вас пока нет сохранённых записей"
    }
  }];
}

const lines = entries.map(entry => {
  const icon =
    entry.json.entry_type === 'observation' ? '📌' :
    entry.json.entry_type === 'insight' ? '💡' :
    '📝';

  return `${icon} ${entry.json.content}`;
});

return [{
  json: {
    reply:
      "📚 Последние записи\n\n" +
      lines.join("\n\n")
  }
}];

const rawText = $json.text || "";
const text = rawText.trim();

if (!text) {
  throw new Error("No text available");
}

if (text.startsWith("/")) {
  return [{
    json: {
      route: "command",
      text: text.startsWith("/help") ? "/start" : text
    }
  }];
}

return [{
  json: {
    route: "tracker",
    text
  }
}];

let voiceText = "";

try {
  voiceText = $('VOI_NormalizeTranscript').first().json.text;
} catch (e) {
  voiceText = "";
}

const telegramText =
  $('TG_Trigger').first()?.json?.message?.text || "";

return [{
  json: {
    text: voiceText || telegramText,
    person_id: $json.person_id,
    conversation_id: $json.conversation_id,
    trajectory_id: $json.trajectory_id,
    current_stage: $json.current_stage,
    sub_stage: $json.sub_stage,
    pattern_type: $json.pattern_type,
    allow_reminders: $json.allow_reminders
  }
}];

let raw = $input.first().json.output || "";
// Очистка от markdown-оберток ```json ... ```
raw = raw.replace(/```json/g, "").replace(/```/g, "").trim();
try {
  return [{ json: JSON.parse(raw) }];
} catch (e) {
  return [{ json: { has_signal: false, error: "Invalid JSON structure" } }];
}
